export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (!env.DB) return htmlResponse(errorPage("Database unavailable", "The database binding is not ready yet."));
      await seedBooks(env.DB);

      if (url.pathname === "/") return htmlResponse(await renderHome(env.DB));
      if (url.pathname === "/admin") return htmlResponse(await renderAdmin(request, env.DB));
      if (url.pathname === "/api/books") return handleBooksApi(request, env.DB);
      if (url.pathname === "/api/analytics") return handleAnalyticsApi(request, env.DB);
      if (url.pathname === "/api/events") return handleEventApi(request, env.DB);
      if (url.pathname.startsWith("/go/")) return handleRedirect(request, env.DB, url.pathname.slice(4));
      if (url.pathname.startsWith("/sample/")) return handleSampleImage(url.pathname.slice(8));

      return new Response("Not found", { status: 404 });
    } catch (error) {
      console.error(error);
      return htmlResponse(errorPage("Something went wrong", "Please refresh and try again."), 500);
    }
  },
};

async function seedBooks(db) {
  const count = await db.prepare("SELECT COUNT(*) AS count FROM books").first();
  if ((count?.count ?? 0) > 0) return;

  const statements = DEFAULT_BOOKS.map((book) =>
    db
      .prepare(
        `INSERT INTO books
          (id, title, age_range, description, amazon_url, asin, cover_url, tags, sort_order, featured, visible)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
      )
      .bind(
        book.id,
        book.title,
        book.ageRange,
        book.description,
        book.amazonUrl,
        book.asin,
        book.coverUrl,
        book.tags,
        book.sortOrder,
        book.featured,
        book.visible
      )
  );
  await db.batch(statements);
}

async function listBooks(db, includeHidden = false) {
  const sql = includeHidden
    ? "SELECT * FROM books ORDER BY sort_order, created_at"
    : "SELECT * FROM books WHERE visible = 1 ORDER BY sort_order, created_at";
  const result = await db.prepare(sql).all();
  return (result.results ?? []).map(rowToBook);
}

