async function handleBooksApi(request, db) {
  const admin = requireAdmin(request);
  if (admin instanceof Response) return admin;

  if (request.method === "GET") return jsonResponse(await listBooks(db, true));

  const payload = await request.json();
  const asin = extractAsin(payload.amazonUrl);
  if (!asin) return jsonResponse({ error: "Please paste a valid Amazon product link with an ASIN." }, 400);
  const id = slugify(payload.id || `${payload.title || "book"}-${asin}`);
  const title = cleanText(payload.title, 160);
  const amazonUrl = `https://www.amazon.com/dp/${asin}`;
  const book = {
    id,
    title,
    ageRange: cleanText(payload.ageRange || "", 50),
    description: cleanText(payload.description || "", 500),
    amazonUrl,
    asin,
    coverUrl: coverUrlForAsin(asin),
    tags: cleanText(payload.tags || "", 300),
    sortOrder: Number.parseInt(payload.sortOrder ?? "50", 10) || 50,
    featured: payload.featured ? 1 : 0,
    visible: payload.visible === false ? 0 : 1,
  };
  if (!book.title || !book.description) return jsonResponse({ error: "Title and description are required." }, 400);

  await db
    .prepare(
      `INSERT INTO books
        (id, title, age_range, description, amazon_url, asin, cover_url, tags, sort_order, featured, visible, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
       ON CONFLICT(id) DO UPDATE SET
        title = excluded.title,
        age_range = excluded.age_range,
        description = excluded.description,
        amazon_url = excluded.amazon_url,
        asin = excluded.asin,
        cover_url = excluded.cover_url,
        tags = excluded.tags,
        sort_order = excluded.sort_order,
        featured = excluded.featured,
        visible = excluded.visible,
        updated_at = CURRENT_TIMESTAMP`
    )
    .bind(
      book.id,
      book.title,
      book.ageRange,
      book.description,
      book.amazonUrl,
      book.asin,
      book.coverUrl,
      book.tags,
      book.sortOrder,
      book.featured,
      book.visible
    )
    .run();

  return jsonResponse({ ok: true, book });
}

async function handleAnalyticsApi(request, db) {
  const admin = requireAdmin(request);
  if (admin instanceof Response) return admin;

  const [totalBooks, totalClicks, totalViews, todayClicks, byBook, recent] = await Promise.all([
    db.prepare("SELECT COUNT(*) AS value FROM books WHERE visible = 1").first(),
    db.prepare("SELECT COUNT(*) AS value FROM analytics_events WHERE event_type = 'amazon_click'").first(),
    db.prepare("SELECT COUNT(*) AS value FROM analytics_events WHERE event_type = 'book_view'").first(),
    db.prepare("SELECT COUNT(*) AS value FROM analytics_events WHERE event_type = 'amazon_click' AND created_at >= datetime('now', '-1 day')").first(),
    db
      .prepare(
        `SELECT b.id, b.title,
          SUM(CASE WHEN e.event_type = 'book_view' THEN 1 ELSE 0 END) AS views,
          SUM(CASE WHEN e.event_type = 'amazon_click' THEN 1 ELSE 0 END) AS clicks
        FROM books b
        LEFT JOIN analytics_events e ON e.book_id = b.id
        GROUP BY b.id, b.title
        ORDER BY clicks DESC, views DESC, b.sort_order`
      )
      .all(),
    db.prepare("SELECT event_type, book_id, device, created_at FROM analytics_events ORDER BY created_at DESC LIMIT 20").all(),
  ]);

  return jsonResponse({
    totals: {
      books: totalBooks?.value ?? 0,
      clicks: totalClicks?.value ?? 0,
      views: totalViews?.value ?? 0,
      todayClicks: todayClicks?.value ?? 0,
    },
    byBook: byBook.results ?? [],
    recent: recent.results ?? [],
  });
}

async function handleEventApi(request, db) {
  if (request.method !== "POST") return new Response("Method not allowed", { status: 405 });
  const payload = await request.json().catch(() => ({}));
  const eventType = ["book_view", "sample_view", "amazon_click", "page_view"].includes(payload.eventType)
    ? payload.eventType
    : "page_view";
  await recordEvent(db, request, eventType, payload.bookId || "", new URL(request.url).pathname);
  return jsonResponse({ ok: true });
}

async function handleRedirect(request, db, bookId) {
  const book = await db.prepare("SELECT * FROM books WHERE id = ? AND visible = 1").bind(bookId).first();
  if (!book) return new Response("Book not found", { status: 404 });
  await recordEvent(db, request, "amazon_click", book.id, new URL(request.url).pathname);
  return Response.redirect(book.amazon_url, 302);
}

async function recordEvent(db, request, eventType, bookId, path) {
  const userAgent = request.headers.get("user-agent") || "";
  await db
    .prepare(
      `INSERT INTO analytics_events (event_type, book_id, path, referrer, user_agent, device)
       VALUES (?, ?, ?, ?, ?, ?)`
    )
    .bind(eventType, bookId, path, request.headers.get("referer") || "", userAgent.slice(0, 500), deviceFromUserAgent(userAgent))
    .run();
}

function handleSampleImage(filename) {
  const image = PREVIEW_IMAGES.find((item) => item.file === filename);
  if (!image) return new Response("Not found", { status: 404 });
  return new Response(base64ToBytes(image.data), {
    headers: {
      "content-type": "image/jpeg",
      "cache-control": "public, max-age=31536000, immutable",
    },
  });
}

function requireAdmin(request) {
  const user = getUser(request);
  if (user.email?.toLowerCase() === ADMIN_EMAIL) return true;
  return jsonResponse({ error: "Admin access denied." }, 403);
}

function getUser(request) {
  return {
    email: request.headers.get("oai-authenticated-user-email") || "",
    id: request.headers.get("oai-authenticated-user-id") || "",
  };
}

function rowToBook(row) {
  return {
    id: row.id,
    title: row.title,
    ageRange: row.age_range,
    description: row.description,
    amazonUrl: row.amazon_url,
    asin: row.asin,
    coverUrl: row.cover_url,
    tags: row.tags ? row.tags.split(",").map((tag) => tag.trim()).filter(Boolean) : [],
    sortOrder: row.sort_order,
    featured: Boolean(row.featured),
    visible: Boolean(row.visible),
  };
}

function extractAsin(value = "") {
  const match = String(value).match(/(?:dp|gp\/product)\/([A-Z0-9]{10})|\/([A-Z0-9]{10})(?:[/?]|$)|^([A-Z0-9]{10})$/i);
  return (match?.[1] || match?.[2] || match?.[3] || "").toUpperCase();
}

function coverUrlForAsin(asin) {
  return `https://m.media-amazon.com/images/P/${asin}.01._SCLZZZZZZZ_SX500_.jpg`;
}

function slugify(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function cleanText(value, max) {
  return String(value || "").replace(/\s+/g, " ").trim().slice(0, max);
}

function deviceFromUserAgent(userAgent) {
  return /mobile|android|iphone|ipad/i.test(userAgent) ? "mobile" : "desktop";
}

function bookJsonLd(books) {
  return {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Children's coloring books for ages 3 to 8",
    itemListElement: books.map((book, index) => ({
      "@type": "ListItem",
      position: index + 1,
      item: {
        "@type": "Book",
        name: book.title,
        bookFormat: "https://schema.org/Paperback",
        audience: `Children ${book.ageRange}`,
        about: book.description,
        url: book.amazonUrl,
        image: book.coverUrl,
      },
    })),
  };
}

