function trackingScript() {
  return `
const seen = new Set();
const postEvent = (eventType, bookId = "") => {
  navigator.sendBeacon?.("/api/events", new Blob([JSON.stringify({ eventType, bookId })], { type: "application/json" }));
};
postEvent("page_view");
document.querySelectorAll("[data-track-click]").forEach((link) => {
  link.addEventListener("click", () => postEvent("amazon_click", link.dataset.trackClick));
});
const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (!entry.isIntersecting) return;
    const id = entry.target.dataset.bookId || "sample-pages";
    const type = entry.target.classList.contains("sample-section") ? "sample_view" : "book_view";
    const key = type + ":" + id;
    if (seen.has(key)) return;
    seen.add(key);
    postEvent(type, id);
  });
}, { threshold: 0.45 });
document.querySelectorAll("[data-book-id], .sample-section").forEach((item) => observer.observe(item));
`;
}

function adminScript() {
  return `
const analyticsEl = document.querySelector("#analytics");
const booksEl = document.querySelector("#admin-books");
const form = document.querySelector("#book-form");

async function loadAdmin() {
  const [books, analytics] = await Promise.all([
    fetch("/api/books").then((res) => res.json()),
    fetch("/api/analytics").then((res) => res.json()),
  ]);
  renderAnalytics(analytics);
  renderBooks(books);
}

function renderAnalytics(data) {
  analyticsEl.innerHTML = [
    metric("Visible books", data.totals.books),
    metric("Amazon clicks", data.totals.clicks),
    metric("Book views", data.totals.views),
    metric("Clicks today", data.totals.todayClicks),
  ].join("") + "<h3>Clicks by book</h3>" + data.byBook.map((row) => (
    "<div class='book-stat'><span>" + escapeText(row.title) + "</span><strong>" + (row.clicks || 0) + " clicks / " + (row.views || 0) + " views</strong></div>"
  )).join("");
}

function metric(label, value) {
  return "<div class='metric'><span>" + label + "</span><strong>" + value + "</strong></div>";
}

function renderBooks(books) {
  booksEl.innerHTML = books.map((book) => (
    "<article class='admin-book'><img src='" + book.coverUrl + "' alt=''><div><h3>" + escapeText(book.title) + "</h3><p>" + escapeText(book.description) + "</p><small>" + escapeText(book.asin) + " · " + (book.visible ? "Visible" : "Hidden") + " · " + (book.featured ? "Featured" : "Standard") + "</small></div></article>"
  )).join("");
}

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  const formData = new FormData(form);
  const payload = Object.fromEntries(formData.entries());
  payload.featured = formData.has("featured");
  payload.visible = formData.has("visible");
  const response = await fetch("/api/books", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  });
  const data = await response.json();
  if (!response.ok) {
    alert(data.error || "Could not save book.");
    return;
  }
  form.reset();
  form.visible.checked = true;
  form.sortOrder.value = "50";
  await loadAdmin();
});

function escapeText(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
}

loadAdmin().catch((error) => {
  analyticsEl.textContent = "Could not load analytics.";
  console.error(error);
});
`;
}

